/**
 * The collection: stats, trait filters, a grid, and one token in detail.
 *
 * Modelled on how a marketplace presents a collection, with one rule that
 * changes what is shown: **every figure here is read from the chain or computed
 * from the contract.** No volume, no floor history, no holder counts pulled
 * from an indexer this project does not have. A stat that cannot be computed
 * honestly is left out rather than invented, which is why the bar is five
 * numbers and not twelve.
 *
 * Rarity comes from `rarity.js`, generated by walking `traitsOf` across the
 * whole supply. That function is pure, so the table is exact rather than
 * sampled, and a test fails if the art changes without it being regenerated.
 */

import { STRINGS } from "./i18n.js";
import { initChrome, prefersReduced } from "./chrome.js";
import { CHAINS, COLLECTIONS, chainOf, collectionById, DEFAULT_COLLECTION, isLive } from "./config.js";
import { createDemo } from "./demo.js";
import { formatUnits } from "./abi.js";
/*
 * The rarity table is chosen at boot, not imported, because which one it is
 * depends on the collection in the URL. Both modules answer the same six
 * names; the dogs pack their tokens into index strings because 5000 spelled
 * out is 484 KB, and that difference stays inside the module.
 */
let RARITY = [];
let LAYERS = [];
let SUPPLY = 0;
let traitsOf = () => null;
let rarestOf = () => 100;
let percentOf = () => 0;
import * as chain from "./chain.js";

const chrome = initChrome(STRINGS, { prefix: "plinth" });
const $ = (id) => document.getElementById(id);
const t = (key) => (STRINGS[chrome.lang()] ?? STRINGS.en)[key] ?? key;

const locale = () => (chrome.lang() === "de" ? "de-DE" : "en-GB");
const pol = (wei) =>
  `${Number(formatUnits(wei)).toLocaleString(locale(), { maximumFractionDigits: 4 })} POL`;
const pct = (n) => `${n.toLocaleString(locale(), { maximumFractionDigits: 1 })}%`;

/**
 * Which collection this page is showing.
 *
 * From `?c=`, falling back to the default rather than erroring, because a
 * mistyped link should land somewhere real. `chain.use` points every read at
 * that collection's chain, which is the whole reason this page can serve one
 * collection on a testnet and another on mainnet.
 */
const shown = collectionById(new URLSearchParams(location.search).get("c") ?? "")
  ?? collectionById(DEFAULT_COLLECTION);

chain.use(shown);

let state = null;
let account = null;

/** Selected filters: layer index -> Set of values. */
const chosen = new Map();

// ------------------------------------------------------------------ backdrop

const ridges = [...document.querySelectorAll(".ridge")];
const reveals = [...document.querySelectorAll(".reveal")];

function onScroll() {
  const limit = window.innerHeight * 0.9;
  for (const el of reveals) {
    if (!el.classList.contains("is-in") && el.getBoundingClientRect().top < limit) {
      el.classList.add("is-in");
    }
  }
  if (prefersReduced) return;
  for (const ridge of ridges) {
    ridge.style.transform = `translateY(${window.scrollY * Number(ridge.dataset.depth ?? 0)}px)`;
  }
}

addEventListener("scroll", onScroll, { passive: true });
addEventListener("resize", onScroll, { passive: true });

// -------------------------------------------------------------------- traits

/**
 * The filter sidebar.
 *
 * Counts are of the whole supply, not of what is currently minted. A trait that
 * is 2.4% of 500 is 2.4% whether twelve tokens exist or all of them, and
 * recomputing it against the minted set would make the same cat look rarer on a
 * quiet day.
 */
function paintFilters() {
  const wrap = $("filter-groups");
  wrap.innerHTML = "";

  RARITY.forEach((group, layerIndex) => {
    const details = document.createElement("details");
    details.open = chosen.has(layerIndex);

    const summary = document.createElement("summary");
    summary.textContent = t(`layer.${LAYERS[layerIndex]}`) ?? group.layer;

    const picked = chosen.get(layerIndex);
    if (picked?.size) {
      const badge = document.createElement("span");
      badge.className = "count";
      badge.textContent = String(picked.size);
      summary.append(badge);
    }

    details.append(summary);

    for (const { value, count, percent } of group.values) {
      const row = document.createElement("label");
      row.className = "trait-row";

      const box = document.createElement("input");
      box.type = "checkbox";
      box.checked = picked?.has(value) ?? false;
      box.addEventListener("change", () => {
        const set = chosen.get(layerIndex) ?? new Set();
        if (box.checked) set.add(value);
        else set.delete(value);

        if (set.size) chosen.set(layerIndex, set);
        else chosen.delete(layerIndex);

        paintFilters();
        paintGrid();
      });

      const name = document.createElement("span");
      name.className = "trait-name";
      name.textContent = value;

      const share = document.createElement("span");
      share.className = "trait-share";
      share.textContent = pct(percent);
      share.title = `${count} of ${SUPPLY}`;

      row.append(box, name, share);
      details.append(row);
    }

    wrap.append(details);
  });
}

/** Does this token pass every active filter? */
function matches(id) {
  const traits = traitsOf(id);
  if (!traits) return false;

  for (const [layerIndex, values] of chosen) {
    if (!values.has(traits[layerIndex])) return false;
  }
  return true;
}

// ---------------------------------------------------------------------- grid

function artFor(token) {
  const wrap = document.createElement("div");
  wrap.className = "art";

  const img = document.createElement("img");
  img.loading = "lazy";
  img.alt = `${shown.name} #${token.id}`;
  img.src = `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(token.svg)))}`;

  wrap.append(img);
  return wrap;
}

function paintGrid() {
  const grid = $("grid");
  grid.innerHTML = "";

  let items = state.tokens.filter((tk) => matches(tk.id));

  const sort = $("sort").value;
  if (sort === "rare") items = [...items].sort((a, b) => rarestOf(a.id) - rarestOf(b.id));
  else if (sort === "price") {
    items = [...items].sort((a, b) => {
      if (a.listed !== b.listed) return a.listed ? -1 : 1;
      return a.price < b.price ? -1 : a.price > b.price ? 1 : 0;
    });
  } else items = [...items].sort((a, b) => Number(a.id - b.id));

  for (const token of items) {
    const card = document.createElement("button");
    card.type = "button";
    card.className = "item glass";
    card.addEventListener("click", () => openToken(token.id));

    const meta = document.createElement("div");
    meta.className = "meta";

    const row = document.createElement("div");
    row.className = "row";

    const id = document.createElement("span");
    id.className = "id";
    id.textContent = `#${token.id}`;

    const price = document.createElement("span");
    price.className = "price";
    price.textContent = token.listed ? pol(token.price) : t("item.unlisted");

    row.append(id, price);

    const rare = document.createElement("span");
    rare.className = "owner";
    rare.textContent = `${t("col.rarest")} ${pct(rarestOf(token.id))}`;

    meta.append(row, rare);
    card.append(artFor(token), meta);
    grid.append(card);
  }

  $("empty").hidden = items.length > 0;
  $("showing").textContent = t("col.showing")
    .replace("{n}", String(items.length))
    .replace("{total}", String(state.tokens.length));
}

// --------------------------------------------------------------- one token

function openToken(id) {
  const token = state.tokens.find((tk) => String(tk.id) === String(id));
  if (!token) return;

  $("t-art").innerHTML = "";
  $("t-art").append(artFor(token));

  // From the collection being shown, never written out. Both of these named a
  // cat on every page, so opening any dog gave it the wrong collection's name.
  $("t-collection").textContent = shown.name;
  $("t-name").textContent = `${shown.name} #${token.id}`;
  $("t-owner").textContent = state.isDemo
    ? token.owner === state.address
      ? t("tok.you")
      : chain.shortAddress(token.owner)
    : chain.shortAddress(token.owner);

  $("t-price").textContent = token.listed ? pol(token.price) : t("item.unlisted");

  // Traits, each with what share of the supply carries it.
  const traits = $("t-traits");
  traits.innerHTML = "";

  const values = traitsOf(token.id) ?? [];
  values.forEach((value, layerIndex) => {
    const cell = document.createElement("div");
    cell.className = "t-trait glass";

    const k = document.createElement("span");
    k.className = "k";
    k.textContent = t(`layer.${LAYERS[layerIndex]}`);

    const v = document.createElement("span");
    v.className = "v";
    v.textContent = value;

    const share = document.createElement("span");
    share.className = "share";
    const p = percentOf(layerIndex, value);
    share.textContent = t("tok.have").replace("{p}", pct(p));
    if (p <= 5) share.classList.add("is-rare");

    cell.append(k, v, share);
    traits.append(cell);
  });

  // Details, all of them checkable by anybody who wants to.
  const details = $("t-details");
  details.innerHTML = "";

  const rows = [
    [t("tok.contract"), shown.collection ? chain.shortAddress(shown.collection) : t("tok.demoOnly")],
    [t("tok.tokenId"), String(token.id)],
    [t("tok.standard"), "ERC-721"],
    [t("tok.chain"), chainOf(shown).name],
    [t("tok.royalty"), token.royalty],
  ];

  for (const [k, v] of rows) {
    if (!v) continue;
    const dt = document.createElement("dt");
    dt.textContent = k;
    const dd = document.createElement("dd");
    dd.textContent = v;
    details.append(dt, dd);
  }

  history.replaceState(null, "", `?id=${token.id}`);
  $("token").showModal();
}

$("token-close").addEventListener("click", () => $("token").close());
$("token").addEventListener("close", () => history.replaceState(null, "", location.pathname));
$("token").addEventListener("click", (event) => {
  // Clicking the backdrop closes it. The dialog element reports those clicks
  // as landing on itself rather than on any child.
  if (event.target === $("token")) $("token").close();
});

// -------------------------------------------------------------------- stats

/**
 * Links to every collection, with each one's chain on the label.
 *
 * Built from the registry rather than written into the markup, so adding a
 * third collection is a config change. The chain is on the pill because these
 * two are not the same kind of thing: one is a testnet you can try for free.
 */
function paintSwitch() {
  const nav = $("col-switch");
  nav.innerHTML = "";

  for (const c of COLLECTIONS) {
    const link = document.createElement("a");
    link.href = `./collection.html?c=${c.id}`;
    link.className = "col-switch-item" + (c.id === shown.id ? " is-here" : "");
    if (c.id === shown.id) link.setAttribute("aria-current", "page");

    const net = CHAINS[c.chain];
    link.innerHTML = `<strong></strong><span></span>`;
    link.querySelector("strong").textContent = c.name;
    link.querySelector("span").textContent = net.testnet
      ? `${net.shortName} · ${t("col.testnet")}`
      : net.shortName;

    nav.append(link);
  }
}

function paintStats() {
  const minted = state.tokens.length;
  const listed = state.tokens.filter((tk) => tk.listed);
  const owners = new Set(state.tokens.map((tk) => tk.owner)).size;

  /*
   * Market figures are shown only when they were read from the chain.
   *
   * The first version of this gated on whether the collection was *deployed*,
   * which is the wrong question and was wrong within the hour: the dogs went
   * live on mainnet, `isLive` flipped true, and the page immediately reported
   * a floor of 0.5 POL and seven listings for a contract with nothing minted
   * on it. In a currency that is real money on that chain.
   *
   * The demo builds invented listings so the marketplace has something to try,
   * and that is fine where it is labelled. It is not fine as a price. So the
   * question is whether these numbers came from the chain, and nothing else.
   *
   * The artwork stays either way, because the contract really drew it.
   */
  const trading = !state.isDemo;

  $("s-items").textContent = trading ? String(minted) : "—";
  $("s-supply").textContent = String(state.supply ?? SUPPLY);
  $("s-owners").textContent = trading ? String(owners) : "—";
  $("s-listed").textContent = trading ? String(listed.length) : "—";

  // Floor is the cheapest thing actually for sale. With nothing listed there is
  // no floor, and a dash says that better than a zero does.
  const floor = listed.reduce((low, tk) => (low === null || tk.price < low ? tk.price : low), null);
  $("s-floor").textContent = !trading || floor === null ? "—" : pol(floor);

  const creator = $("col-creator");
  creator.textContent = state.isDemo ? t("wallet.demoAccount") : chain.shortAddress(state.address);
  creator.href = state.isDemo ? "#" : `${chainOf(shown).explorer}/address/${state.address}`;

  // The collection's own identity, so one page can serve both.
  $("col-title").textContent = shown.name;
  $("col-desc").textContent = t(`col.desc.${shown.id}`);
  document.title = `${shown.name} · plinth`;

  /*
   * Which chain, said plainly, and whether it is a testnet.
   *
   * The two collections are priced in currencies that are not comparable: POL
   * on Amoy is free from a faucet, POL on Polygon is money. A floor of 0.5
   * means two entirely different things depending on this label, so it is not
   * a decoration and it is never omitted.
   */
  const net = chainOf(shown);
  const badge = $("col-chain");
  badge.textContent = net.testnet ? `${net.shortName} · ${t("col.testnet")}` : net.shortName;
  badge.classList.toggle("is-testnet", net.testnet);

  // Nothing deployed yet is a fact about the collection, not a failure.
  $("col-pending").hidden = isLive(shown);
  $("col-mint").hidden = !isLive(shown);

  paintSwitch();

  // The avatar is token 1's artwork, so the collection is represented by
  // something the contract actually produced.
  const first = state.tokens[0];
  if (first) {
    $("col-avatar").innerHTML = "";
    $("col-avatar").append(artFor(first));
  }
}

// ------------------------------------------------------------------- wiring

$("clear").addEventListener("click", () => {
  chosen.clear();
  paintFilters();
  paintGrid();
});

$("sort").addEventListener("change", paintGrid);

/** The nav's account state. The grid below is the same either way. */
function paintAccount() {
  $("connect").textContent = account ? chain.shortAddress(account) : t("nav.connect");
  $("signout").hidden = !account;
}

$("connect").addEventListener("click", async () => {
  if (!chain.hasWallet() || !isLive(shown)) return;
  try {
    account = await chain.connect();
    await loadLive();
    paintAccount();
  } catch {
    /* the marketplace page reports connection errors; here it just stays demo */
  }
});

/**
 * Mint one of whichever collection this page is showing.
 *
 * The chain switch is the part that matters. The two collections live on
 * different networks and share contract addresses, so a mint signed while the
 * wallet is on the wrong one is not an error anybody sees: it is a transaction
 * that succeeds against a different contract. `ensureChain` moves the wallet
 * first and the mint only goes out afterwards.
 */
async function doMint() {
  const note = $("mint-note");
  const show = (key, bad = false) => {
    note.textContent = t(key);
    note.classList.toggle("is-bad", bad);
    note.hidden = false;
  };

  if (!chain.hasWallet() || !account) {
    show("col.mintConnect", true);
    return;
  }

  const button = $("mint-here");
  button.disabled = true;

  try {
    show("col.mintSwitch");
    await chain.ensureChain();

    show("col.mintSigning");
    const { hash } = await chain.send({ ...chain.tx.mint(account), from: account }, () =>
      show("col.mintMining"));

    note.innerHTML = "";
    const link = document.createElement("a");
    link.href = chain.explorerTx(hash);
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = t("col.mintDone");
    note.append(link);

    await loadLive();
  } catch (error) {
    // Sold out is a real answer from the contract, not a fault.
    show(String(error?.message ?? "").includes("SoldOut") ? "col.mintSoldOut" : "col.mintRefused", true);
  } finally {
    button.disabled = false;
  }
}

$("mint-here").addEventListener("click", doMint);

$("signout").addEventListener("click", async () => {
  await chain.disconnect();
  location.reload();
});

chrome.onLangChange(() => {
  paintFilters();
  paintGrid();
  paintStats();
});

async function loadLive() {
  const minted = await chain.totalMinted();
  const supply = await chain.maxSupply();

  const tokens = [];
  for (let id = 1n; id <= minted; id++) {
    const listing = await chain.listingOf(id);
    const listed = listing.seller !== "0x0000000000000000000000000000000000000000";
    const meta = chain.metaFrom(await chain.tokenURI(id));

    tokens.push({
      id,
      svg: atob(meta.image.split(";base64,")[1]),
      royalty: meta.attributes?.find((a) => /royalty/i.test(a.trait_type))?.value ?? "",
      owner: listed ? listing.seller : await chain.ownerOf(id),
      listed,
      price: listing.price,
    });
  }

  state = { isDemo: false, address: account, supply, tokens };
  paintAll();
}

function paintAll() {
  paintAccount();
  paintStats();
  paintFilters();
  paintGrid();
  onScroll();

  // A shared link opens straight onto its token.
  const wanted = new URLSearchParams(location.search).get("id");
  if (wanted) openToken(wanted);
}

/**
 * Load the rarity table and the artwork this collection needs.
 *
 * Both are per-collection and both are large enough that shipping the pair to
 * a visitor looking at the other one would be waste: the dog rarity table is
 * 63 KB and its artwork another 39. A dynamic import fetches only the one in
 * the URL.
 */
async function loadCollection() {
  const rarity = await import(shown.rarity);

  RARITY = rarity.RARITY;
  LAYERS = rarity.LAYERS;
  SUPPLY = rarity.SUPPLY;
  traitsOf = rarity.traitsOf;
  rarestOf = rarity.rarestOf;
  percentOf = rarity.percentOf;

  // Artwork the contract drew, rendered once and committed, because browsers
  // cannot compute keccak256. It is what the grid shows before anybody
  // connects, on both collections. Nothing is minted on the dogs yet, so for
  // them it is currently the only artwork there is to show.
  const art = shown.id === "cats"
    ? (await import("./demo-art.js")).DEMO_ART
    : (await import("./dog-demo-art.js")).DOG_DEMO_ART;

  state = createDemo(art);
}

async function boot() {
  await loadCollection();

  if (isLive(shown) && chain.hasWallet()) {
    const existing = await chain.currentAccount();
    if (existing && (await chain.currentChainId()) === chainOf(shown).hex) {
      account = existing;
      try {
        await loadLive();
        return;
      } catch {
        /* fall through to the demo rather than showing a broken collection */
      }
    }
  }
  paintAll();
}

boot();
